def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # The final round has no future, so defection strictly dominates.
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0

    recent_start = n - 10 if n >= 10 else 0
    recent_n = 0
    recent_opp_d = 0

    # Evidence about how the opponent responds one round after our defection.
    c_after_my_d = 0
    d_after_my_d = 0

    prev_my = 'C'

    for i in range(n):
        me, op = history[i]

        if me == 'D':
            my_d += 1
        if op == 'D':
            opp_d += 1

        if i >= recent_start:
            recent_n += 1
            if op == 'D':
                recent_opp_d += 1

        if i > 0 and prev_my == 'D':
            if op == 'C':
                c_after_my_d += 1
            else:
                d_after_my_d += 1

        prev_my = me

    defect_rate = opp_d / n

    # Against essentially always-defect opponents, never forgive; take DD=1.
    if defect_rate >= 0.70 or (recent_n >= 8 and recent_opp_d >= recent_n - 1):
        return 'D'

    # If the opponent has never defected, cooperate until a safe endgame probe.
    if opp_d == 0:
        if my_d > 0:
            return 'D'
        return 'D' if n >= 98 else 'C'

    # Forgiving means the opponent often cooperates after we defected.
    # Use this to exploit generous/non-retaliatory behavior, but only when
    # the evidence is clear enough to avoid long retaliation cycles.
    forgiving = (
        c_after_my_d > d_after_my_d and
        c_after_my_d + d_after_my_d >= 2
    )

    if opp_last == 'D':
        # Mostly cooperative opponent: punish unprovoked D once, then try to
        # restore cooperation after a mutual-D response.
        if defect_rate < 0.35:
            if my_last == 'D':
                if forgiving or (recent_n >= 4 and recent_opp_d <= 2):
                    return 'C'
                return 'D'
            return 'D'

        # Mixed opponent: reciprocal pressure with trap-breaking.
        if defect_rate < 0.60:
            if my_last == 'D':
                if forgiving or (recent_opp_d * 2 <= recent_n):
                    return 'C'
                return 'D'
            return 'D'

        # High-defect opponent: mostly defect, but if the recent window has
        # clearly turned cooperative, make a deterministic repair attempt.
        if recent_n >= 8 and recent_opp_d <= 2:
            return 'C'
        return 'D'

    # opp_last == 'C'
    # If we just defected and the opponent forgave, continue extracting DC=5
    # until there is evidence they may retaliate.
    if my_last == 'D' and forgiving and defect_rate < 0.55:
        return 'D'

    # Late-game exploitation against cooperative or forgiving behavior.
    if n >= 98:
        if defect_rate < 0.30 or forgiving or my_last == 'D':
            return 'D'
        return 'C'

    # Default: maintain mutual cooperation.
    return 'C'
